import ast
from pathlib import Path

def collected_test_names_logic(paths):
    names = {}
    for path in paths:
        names[path.name] = {n.name for n in ast.walk(ast.parse(path.read_text(encoding='utf-8')))
                            if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)) and n.name.startswith('test')}
    return names

def test_collected_test_names_only_test_underscore():
    dummy_file = Path("tests/test_dummy_c07_s2.py")
    dummy_file.write_text("def test_valid(): pass\ndef testinvalid(): pass", encoding='utf-8')
    try:
        results = collected_test_names_logic([dummy_file])
        test_names = results[dummy_file.name]
        assert "testinvalid" not in test_names, "Should not include functions starting with 'test' but lacking underscore"
        assert "test_valid" in test_names
    finally:
        if dummy_file.exists():
            dummy_file.unlink()
